&lt;div class=&quot;job-post-container&quot; style=&quot;position: relative; background-color: white; padding: 20px; max-width: 1000px; margin: 0 auto; box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.1); min-height: 500px; border: 5px solid #000000; font-family: &#39;Geist&#39;, sans-serif; font-weight: 300;&quot;&gt;
